sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {

        //MSSTRESURY-314        

        // Call the function specific to Treasury Case
        var caseQuery = new TreasuryCaseUtils().getTreasuryCaseQuery();

        // If the query is null, restrict access to all records
        if (!caseQuery) {
            current.setAbortAction(true); // No access if no market groups are found
            return;
        }

        // Apply the query to restrict access
        current.addEncodedQuery(caseQuery);

    } catch (error) {
        // Log the error for debugging purposes
        gs.error('[iQube - Treasury]: Error in Business Rule = TreasuryTransactionThresholdDynamicGroup | Before Query Business Rule for Treasury Case: ' + error.message);
        current.setAbortAction(true); // Restrict access if an error occurs
		new x_hsb11_mss_tsd.MSS_Treasury_XMatter_ITID_WidgetFailureHandler().createITIDEvent("MINOR", '[iQube - Treasury]: Error in Business Rule = TreasuryTransactionThresholdDynamicGroup | Before Query Business Rule for Treasury Case: ' + error.message, 'MSSiQubeSN');
    }
})(current, previous);
